public static void assertSameAfterSerialization_1_oe(final String msg, final Object o) { try { // write object to byte buffer final ByteArrayOutputStream baos = new ByteArrayOutputStream();
}
}

// removed other assertion
            final ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(o);
            oos.close();

            // read same object from byte buffer
            final InputStream is = new ByteArrayInputStream(baos.toByteArray());
            final ObjectInputStream ois = new ObjectInputStream(is);
            final Object object = ois.readObject();
            ois.close();

            // assert that original object and deserialized objects are the same
            assertSame(msg, o, object);

